const lessons = [
  lesson('What Future Are You Buying?', 'Before we talk about an investment, we need to know what future the money is meant to serve.', [
    'Ivy enters the Exchange with a list of things she wants to change: more breathing room, a safer home, fewer emergencies that feel like personal failures, and a future that does not depend on one perfect month.',
    'At the first counter, the attendant asks, “What are you investing for?” Ivy starts naming products. Eli starts naming percentages. Sage taps the brass token against the counter. “Those are tools and measurements. I asked for the future.”',
    'They write three possible futures on a glass wall: money needed soon, money protected for a known milestone, and money that may stay committed for a long time. The same dollar cannot be equally available for all three jobs.',
  ], ['Investing is allocating resources toward a future purpose with uncertain results.', 'A goal gives the decision a time horizon, access need, and definition of success.', 'A product name cannot tell you whether the money fits the future it is supposed to serve.'], ['Future goals appear in emergency reserves, education, housing, retirement, flexibility, caregiving, and the ability to leave a bad situation.', 'A person may have multiple goals with different timeframes and different tolerance for loss.', 'The pressure to “start investing” can hide the more important question of what the money must do first.'], ['What is driving the urge: curiosity, a real goal, fear of falling behind, social comparison, a need for escape, or a belief that investing will repair a present shortfall?', 'What would a temporary loss mean for this particular goal?', 'Which future is being protected, expanded, or gambled with?'], { prompt: 'Which detail must come before comparing investment products?', options: [{ id: 'a', label: 'The product with the highest recent return', isCorrect: false }, { id: 'b', label: 'The future purpose, timing, and access need', isCorrect: true }, { id: 'c', label: 'What everyone online is buying', isCorrect: false }] }, { prompt: 'Ivy has money she may need for a major expense next year. What question keeps the decision honest?', options: [{ id: 'a', label: 'Which option has the most exciting upside?', strength: 'developing', feedback: 'Excitement does not tell Ivy whether a temporary loss or limited access would damage the goal.' }, { id: 'b', label: 'What must remain available, and what could change in value before then?', strength: 'strong', feedback: 'This keeps purpose, time, access, and uncertainty visible before a product enters the conversation.' }, { id: 'c', label: 'Which account makes her feel like an investor?', strength: 'developing', feedback: 'The identity can be motivating, but it cannot substitute for a fit between money and future purpose.' }] }, 'When I think about investing, the future I am actually trying to create or protect is…', 'Write one future goal, the approximate time horizon, and what access to the money would mean if life changed.', 'I can name the future before I compare the tool.', 'Ivy and Eli enter the Exchange with purpose, but the first booth is selling ownership itself. The next lesson asks what ownership actually means.', ['investorBasics', 'allocation']),

  lesson('Consumption, Ownership, and the Claim', 'Ownership is not a magic category. It is a claim with rights, limits, uncertainty, and responsibility attached.', [
    'The next hall is split in two. On one side, people exchange money for immediate use: food, shelter, transportation, experiences, tools. On the other, people exchange money for a claim on something that may produce value later.',
    'Ivy points at a polished sign that says OWN IT. “So everything on this side makes me wealthier?”',
    '“No,” Sage says. “A thing can be useful, meaningful, expensive, resalable, income-producing, or none of those. Ownership describes a relationship to something. It does not guarantee the result.”',
    'Eli notices the fine print under the sign: voting rights, maintenance, debt, market price, access restrictions, fees, and the possibility that the thing is worth less when he needs to leave.',
  ], ['An asset is something that may provide future economic benefit, but its value and access can change.', 'Ownership is a claim or relationship that comes with rights and responsibilities.', 'Price, usefulness, ownership, income, and future value are related but not interchangeable.'], ['Ownership appears in securities, real property, business interests, intellectual property, equipment, and other claims.', 'Some assets can be sold quickly; others are slow, costly, or difficult to value.', 'A purchase can feel like ownership while still being primarily consumption or a liability claim.'], ['What exactly is owned: a share, a debt claim, a use right, a physical thing, a contract, or an expectation?', 'Who bears the costs, losses, maintenance, and decisions?', 'Is the ownership claim understood, or is the emotional appeal doing the explaining?'], { prompt: 'What makes an ownership decision more than a label?', options: [{ id: 'a', label: 'Knowing the claim, rights, costs, and possible outcomes', isCorrect: true }, { id: 'b', label: 'Calling the purchase an asset', isCorrect: false }, { id: 'c', label: 'Believing ownership always beats renting', isCorrect: false }] }, { prompt: 'A friend says a purchase is automatically an investment because it can be resold. What should Ivy examine?', options: [{ id: 'a', label: 'Whether the resale story includes price, costs, time, and demand', strength: 'strong', feedback: 'Resale possibility is only one part of the claim; the full exchange includes carrying costs, liquidity, uncertainty, and who might buy later.' }, { id: 'b', label: 'Whether the item looks expensive', strength: 'developing', feedback: 'Appearance can signal status or quality, but it does not establish future economic value.' }, { id: 'c', label: 'Whether other people call it an investment', strength: 'developing', feedback: 'Labels travel faster than evidence. Ivy needs to inspect the claim itself.' }] }, 'A purchase in my life that I call an investment may actually be serving a different job because…', 'Choose one recent or imagined purchase and map its use, ownership claim, costs, resale uncertainty, and future purpose.', 'I can separate the thing I own from the story I tell about it.', 'The Exchange has shown them the difference between owning a claim and owning a promise. Now the booths split into ownership, lending, and containers.', ['investorBasics', 'finraRisk']),

  lesson('Ownership Is Not One Door', 'There is more than one way for money to participate in a future. The door matters.', [
    'Three illuminated doors open at once. The first offers an ownership claim. The second offers a lending claim. The third is a container that can hold either one, or several other things.',
    'Eli walks through the container door and looks around. “This room is empty.”',
    'Sage smiles. “Exactly. An account can hold an investment, but the account is not automatically the investment. The tax treatment, access rules, fees, and protections may differ from what sits inside it.”',
    'Ivy returns to the first two doors. One claim may rise or fall with an organization’s value. Another may promise repayment under terms, but still carry default, interest-rate, inflation, or market risk. Neither door is a guarantee machine.',
  ], ['Equity represents an ownership claim; debt represents a lending claim with repayment terms.', 'An account or plan is a container with rules; it does not explain the asset held inside it.', 'The same investment can behave differently inside different account structures because access, taxes, and rules differ.'], ['Stocks, funds, bonds, notes, real estate interests, retirement accounts, and cash accounts are not interchangeable categories.', 'A person can own an investment directly or through a fund or plan.', 'The words “safe,” “long-term,” and “retirement” can describe a goal or container, not the absence of risk.'], ['What is the legal or economic claim?', 'What can change the value or repayment path?', 'What rules govern access, taxes, fees, voting, withdrawal, or transfer?'], { prompt: 'Which statement is most accurate?', options: [{ id: 'a', label: 'A retirement account is itself a guaranteed investment', isCorrect: false }, { id: 'b', label: 'An account is a container whose contents and rules must be examined', isCorrect: true }, { id: 'c', label: 'Ownership and lending have identical risks', isCorrect: false }] }, { prompt: 'Eli sees a retirement account with a familiar name and stops reading. What is missing?', options: [{ id: 'a', label: 'The investments inside it and the account’s rules', strength: 'strong', feedback: 'The container and its contents have to be examined separately, including access, costs, and possible loss.' }, { id: 'b', label: 'A more impressive account name', strength: 'developing', feedback: 'A name does not tell Eli what the money owns or how it can behave.' }, { id: 'c', label: 'A promise that the balance cannot fall', strength: 'developing', feedback: 'A retirement purpose does not remove investment risk.' }] }, 'The difference between a container and what it contains matters to me because…', 'Draw or describe one container, the investment inside it, the access rules, and the risks that belong to each layer.', 'I can identify the door, the room, and what is actually inside the room.', 'They can now name the claim. The Exchange sends them to the market hall, where familiar investment types become visible.', ['investorBasics', 'irsRetirement']),

  lesson('Stocks, Funds, Bonds, and Real Things', 'A ticker, a fund, a bond, and a building can all carry value—but they do not carry the same claim.', [
    'The market hall displays four living maps. One follows companies. One gathers many investments into a basket. One shows a repayment schedule. One shows a physical property with tenants, repairs, taxes, and an exit door that is not always nearby.',
    'Ivy tries to choose the brightest map. Eli tries to choose the map with the least movement. Sage makes them describe each one without using the words “good,” “bad,” or “safe.”',
    'The descriptions become more useful: ownership, lending, pooled exposure, income, price movement, management, concentration, liquidity, maintenance, default, and uncertainty.',
  ], ['Stocks generally represent equity claims; bonds generally represent debt claims; funds pool investor money under a stated objective.', 'Real assets can have use, income, maintenance, legal, market, and liquidity considerations.', 'An investment category is a starting point for questions, not a complete decision.'], ['The labels appear in employer plans, brokerage accounts, real-estate arrangements, savings products, and alternative assets.', 'A fund may diversify while still concentrating in one sector, region, or theme.', 'A physical asset may feel more tangible without being easier to value or sell.'], ['Can the learner explain what creates value and what can damage the claim?', 'What does the investor depend on: a company, borrower, manager, tenant, market, platform, or physical condition?', 'Is the attraction evidence, familiarity, tangibility, or a promise of control?'], { prompt: 'What is the most useful first question about an investment type?', options: [{ id: 'a', label: 'What claim do I receive and what can change it?', isCorrect: true }, { id: 'b', label: 'How exciting is its recent price movement?', isCorrect: false }, { id: 'c', label: 'Does it sound sophisticated?', isCorrect: false }] }, { prompt: 'Ivy is comparing a fund, a bond, and a rental property. What keeps the comparison honest?', options: [{ id: 'a', label: 'Compare only the advertised return', strength: 'developing', feedback: 'Advertised return hides costs, uncertainty, labor, access, and the conditions required for that result.' }, { id: 'b', label: 'Describe the claim, value source, costs, risks, access, and responsibilities for each', strength: 'strong', feedback: 'Different assets need a common decision frame without pretending they are the same thing.' }, { id: 'c', label: 'Choose the asset that feels most tangible', strength: 'developing', feedback: 'Tangibility can feel reassuring, but it does not remove maintenance, valuation, or market risk.' }] }, 'The investment type I understand best is… The part I still cannot explain is…', 'Make a four-row comparison of an equity claim, debt claim, pooled investment, and real asset. Leave any unknowns visible.', 'I can explain the claim before I compare the price.', 'The maps are understandable enough to question, but every map can move. The next hall is called Risk, and it is not dimmed for comfort.', ['investorBasics', 'finraFunds', 'treasury']),

  lesson('Risk Is More Than Losing Money', 'Risk is not one number. It is the possibility that a future need and a future result do not meet.', [
    'The Risk hall has no walls. Its floor shifts under every booth. Some displays move daily, some move slowly, and some remain still until the moment a person needs to sell.',
    'Ivy asks, “Which one is risky?” Sage answers, “Which risk are you asking about?”',
    'They name price loss, permanent loss, delayed access, inflation, interest-rate change, default, concentration, fraud, fees, forced selling, and the risk of needing money at the wrong time.',
    'Eli admits he has been calling anything that moves “dangerous” and anything that does not move “safe.” Sage points to a quiet display whose value is being eroded slowly by rising prices. “Stillness is not the same as protection.”',
  ], ['Risk includes uncertainty about value, return, access, timing, repayment, purchasing power, and behavior.', 'Volatility is movement; it is not identical to permanent loss, but movement can matter if access is needed.', 'Risk cannot be eliminated, only understood and managed within a decision.'], ['Risk appears in markets, property, lending, inflation, concentration, account access, scams, and personal capacity.', 'The same investment can carry different consequences depending on time horizon and dependence on the money.', 'A person’s ability to wait, absorb loss, or keep contributing changes the practical risk.'], ['Which outcome would damage this goal most?', 'What is the difference between a temporary decline and a permanent impairment?', 'What does the person believe they will do when the value moves against them?'], { prompt: 'Which statement keeps risk visible?', options: [{ id: 'a', label: 'Long-term means risk disappears', isCorrect: false }, { id: 'b', label: 'Risk depends on the claim, time, access, and possible outcomes', isCorrect: true }, { id: 'c', label: 'A stable price proves safety', isCorrect: false }] }, { prompt: 'Eli says he can tolerate risk because he will not need the money for years. What else should he examine?', options: [{ id: 'a', label: 'Whether the claim, time horizon, and behavior under loss still fit', strength: 'strong', feedback: 'Time can help, but it does not erase the possibility of loss, poor fit, forced decisions, or an emotional reaction that changes the plan.' }, { id: 'b', label: 'Nothing—the time horizon answers everything', strength: 'developing', feedback: 'Time matters, but it is only one lens.' }, { id: 'c', label: 'Whether the investment has a dramatic logo', strength: 'developing', feedback: 'Branding cannot measure risk capacity or risk exposure.' }] }, 'A risk I tend to notice quickly is… A risk I may be tempted to ignore is…', 'For one future goal, list five different risks: value, access, timing, purchasing power, and behavior.', 'I can name the kind of risk before I decide whether I can live with it.', 'Risk has stopped being a scary cloud. Now time enters the Exchange, where patience can help but cannot perform miracles.', ['finraRisk', 'allocation']),

  lesson('Time, Growth, and Compounding', 'Time can change the shape of a result. It cannot promise the result.', [
    'In the Time Gallery, every path stretches farther than the eye can see. A small stream of contributions grows into branching lines, but some paths dip, stall, or end at locked gates.',
    'Ivy wants to skip to the last room. Eli wants a guarantee that the line only goes up. Sage points to the places where contributions, reinvestment, fees, taxes, inflation, and time interact.',
    '“Compounding is not a spell,” Sage says. “It is what happens when returns remain invested and time gives the process more opportunities. The underlying result still matters.”',
  ], ['Compounding can occur when returns remain invested and generate additional returns over time.', 'Time horizon affects how much uncertainty a person may be able to withstand, but it does not remove risk.', 'Contributions, fees, taxes, inflation, and actual returns affect the future result.'], ['Time appears in retirement, education, home goals, business ownership, debt repayment, and long-term care planning.', 'Small repeated actions can matter without making any specific result guaranteed.', 'A calculator can illustrate assumptions; it cannot turn assumptions into a forecast.'], ['What assumption is doing the work in the projection?', 'What happens if contributions stop, returns differ, fees rise, or the money is needed sooner?', 'Is the desire for a long horizon a grounded capacity or a way to avoid looking at present constraints?'], { prompt: 'What is the honest way to talk about compounding?', options: [{ id: 'a', label: 'It guarantees that money grows', isCorrect: false }, { id: 'b', label: 'It illustrates how time and reinvested returns can interact under assumptions', isCorrect: true }, { id: 'c', label: 'It removes the need to understand the investment', isCorrect: false }] }, { prompt: 'A projection shows a large future balance. What should Ivy ask before feeling reassured?', options: [{ id: 'a', label: 'What assumptions, costs, contributions, and access needs sit behind the projection?', strength: 'strong', feedback: 'A projection is a model. Its value comes from understanding the assumptions and how sensitive the result is to change.' }, { id: 'b', label: 'Whether the number is exciting enough', strength: 'developing', feedback: 'Excitement does not reveal whether the assumptions fit Ivy’s life.' }, { id: 'c', label: 'Whether the line on the chart is green', strength: 'developing', feedback: 'Color can make a projection persuasive without making it reliable.' }] }, 'When I hear “let time work,” I want to remember that…', 'Use a compound-growth calculator with three different assumptions. Record what changes when time, contribution, return, fees, or inflation changes.', 'I can use a projection as a question, not a promise.', 'The longer paths are visible. Next, the Exchange asks whether spreading exposure can reduce one kind of risk without pretending to eliminate all risk.', ['compound', 'allocationGuide']),

  lesson('Diversification Without the Fairy Tale', 'Diversification can reduce concentration. It cannot make every outcome safe.', [
    'The Exchange opens a bridge made of hundreds of narrow planks. One bridge holds a single company. Another holds a whole market. A third looks broad but all its planks lead to the same industry.',
    'Eli points to the widest bridge. “That one is diversified.”',
    'Sage asks him to look down. Every plank is tied to the same economic event. “Counting holdings is not the same as understanding concentration.”',
    'Ivy sees the useful middle: different assets, issuers, sectors, regions, and sources of risk can behave differently. The bridge can still shake. It simply may not depend on one plank.',
  ], ['Diversification spreads exposure across investments or asset categories.', 'It can reduce concentration risk but cannot eliminate market-wide loss, inflation, fees, or poor fit.', 'A fund or large number of holdings does not automatically mean meaningful diversification.'], ['Diversification appears in portfolios, employer plans, funds, property, income sources, and household dependencies.', 'Correlation matters because holdings that move together may provide less protection than their count suggests.', 'Over-diversification can also make a decision difficult to understand.'], ['What risk is being reduced, and what risk remains?', 'Are the holdings truly different in value source and behavior?', 'Is diversification being used to support understanding or to excuse avoiding it?'], { prompt: 'What can diversification realistically do?', options: [{ id: 'a', label: 'Reduce concentration risk while leaving other risks visible', isCorrect: true }, { id: 'b', label: 'Guarantee that the portfolio will not lose value', isCorrect: false }, { id: 'c', label: 'Make research unnecessary', isCorrect: false }] }, { prompt: 'Ivy owns five investments that all depend on the same sector. What is the hidden issue?', options: [{ id: 'a', label: 'The number five is too small in every situation', strength: 'developing', feedback: 'The count alone does not answer the question; the shared exposure does.' }, { id: 'b', label: 'The investments may be concentrated despite appearing spread out', strength: 'strong', feedback: 'Different labels can still depend on the same economic driver.' }, { id: 'c', label: 'Diversification is never useful', strength: 'developing', feedback: 'Diversification can be useful when it reduces meaningful concentration and remains understandable.' }] }, 'A concentration I already carry may be in my…', 'List the major sources your future depends on: one employer, one asset, one borrower, one market, one platform, or one skill. Mark what is actually diversified and what only looks different.', 'I can distinguish variety of labels from variety of risk.', 'The bridge steadies, but every plank has a toll. The next part of the Exchange makes costs visible.', ['finraDiversify', 'allocation']),

  lesson('Fees, Taxes, Inflation, and Access', 'A return is not the same thing as what remains available for the life you are trying to build.', [
    'The Toll Hall is crowded with tiny doors. Every door takes a little: trading costs, management fees, account charges, taxes, inflation, penalties, spreads, maintenance, or time spent managing the asset.',
    'Ivy asks why the doors are so small. Sage answers, “Because small costs are easier to ignore. They still compound.”',
    'Eli finds a display with a high projected return and a locked exit. Ivy finds a lower projected return with clearer access. Neither answer is complete until the goal, time, taxes, fees, and availability are considered together.',
  ], ['Fees reduce the amount of money that remains invested or available.', 'Taxes and inflation can change real purchasing power and real return.', 'Liquidity is the ability to access or sell an asset; access can carry timing, price, tax, or penalty consequences.'], ['Costs appear in funds, accounts, property, loans, transactions, advice, platforms, and tax structures.', 'A tax-advantaged container can still hold an investment with risk and fees.', 'Money that grows but cannot be accessed when needed may not serve the current job.'], ['Which cost is explicit, which is embedded, and which is paid in time or flexibility?', 'What happens if the money must be accessed early?', 'Is the lower visible cost hiding a higher dependency or exit cost?'], { prompt: 'What should a real-return conversation include?', options: [{ id: 'a', label: 'Only the advertised growth rate', isCorrect: false }, { id: 'b', label: 'Growth, fees, taxes, inflation, access, and the goal’s timing', isCorrect: true }, { id: 'c', label: 'Only the account’s brand', isCorrect: false }] }, { prompt: 'Eli compares two investments by headline return alone. What does Sage ask him to add?', options: [{ id: 'a', label: 'The full cost, tax context, access, and purchasing power', strength: 'strong', feedback: 'The amount that matters is what remains and whether it arrives when the goal needs it.' }, { id: 'b', label: 'A more dramatic forecast', strength: 'developing', feedback: 'A bigger forecast does not expose what the investor pays or gives up.' }, { id: 'c', label: 'The number of social-media followers', strength: 'developing', feedback: 'Popularity is not a cost or return measure.' }] }, 'A cost I might overlook because it is small, automatic, or delayed is…', 'Create a cost map for one imagined investment: visible fees, embedded costs, taxes, inflation exposure, access limits, and time required.', 'I can ask what remains, not just what is advertised.', 'The Exchange has a new rule: no one may buy what they cannot explain. That rule becomes difficult when the lights get louder.', ['fees', 'irsRetirement', 'finraNew']),

  lesson('The Question Before “Should I Buy?”', 'Understanding is not a personality trait. It is a condition for making a choice you can own.', [
    'At the Explanation Booth, the attendant asks each visitor to describe an investment in plain language. The line disappears whenever someone says, “I just know it will go up.”',
    'Ivy is embarrassed when she cannot explain a product she has been watching for months. Eli is relieved when he realizes confidence and understanding are not the same thing.',
    'Sage gives them a question card: What is it? How does it create value? What can make it lose value? What does it cost? When can I access it? Who gets paid? What would make me change my mind?',
  ], ['Due diligence means gathering and testing relevant information before committing.', 'A person can understand the category while not understanding a particular product, provider, or claim.', 'Not knowing is a reason to pause and learn, not a reason to feel ashamed.'], ['This appears in prospectuses, disclosures, contracts, fee schedules, account rules, property documents, and provider registrations.', 'A recommendation can still require independent understanding.', 'The pressure to act now often competes with the time needed to verify.'], ['What emotional cost is attached to admitting “I do not understand this yet”?', 'Is the person seeking information or seeking permission to stop questioning?', 'What evidence would change the decision?'], { prompt: 'What is a sound response to “I cannot explain this investment yet”?', options: [{ id: 'a', label: 'Buy a small amount so the learning becomes real', isCorrect: false }, { id: 'b', label: 'Pause and identify what must be understood before deciding', isCorrect: true }, { id: 'c', label: 'Assume the person recommending it already did the work', isCorrect: false }] }, { prompt: 'A provider says the details are too complicated to explain. What is the strongest next step?', options: [{ id: 'a', label: 'Treat complexity as proof of sophistication', strength: 'developing', feedback: 'Complexity can be real, but it is not evidence that the product fits or deserves trust.' }, { id: 'b', label: 'Request plain-language explanations and verify the documents and provider', strength: 'strong', feedback: 'A decision becomes more defensible when the claim, costs, risks, and provider can be examined.' }, { id: 'c', label: 'Let urgency make the decision', strength: 'developing', feedback: 'Urgency is a pressure; it is not due diligence.' }] }, 'Something I need to understand before I put money into it is…', 'Write a plain-language explanation of one investment category and list the unanswered questions that would stop you from claiming full understanding.', 'I can make “not yet” a responsible financial answer.', 'Now the Exchange turns up the heat: some booths are selling certainty, speed, and identity instead of evidence.', ['investorBasics', 'finraNew', 'ftcScams']),

  lesson('Investing or Speculating?', 'The difference is not whether the price can rise. It is whether the decision can survive an honest explanation of uncertainty.', [
    'The loudest hall is called NOW. Screens flash dramatic gains. A host shouts that hesitation is the only real loss. Eli feels a familiar heat in his chest: the fear that everyone else is getting ahead.',
    'Ivy asks what the assets do. The host points to a chart. Sage asks what creates value, what supports the price, and what happens if the crowd leaves. The host turns the music up.',
    'Outside, Sage draws two circles. Investing begins with a claim, purpose, evidence, and acceptance of uncertainty. Speculation may depend more heavily on price movement, timing, crowd behavior, or a hoped-for exit. The circles can overlap, but they are not synonyms.',
  ], ['Speculation is a decision heavily dependent on uncertain price movement or a future buyer.', 'Investing still carries risk, but it involves examining the underlying claim, purpose, costs, and uncertainty.', 'Calling something “long-term” does not automatically turn speculation into investing.'], ['This appears in concentrated assets, collectibles, crypto, options, real estate flips, trend-driven funds, and viral opportunities.', 'A person may speculate knowingly or accidentally.', 'The emotional experience—urgency, identity, fear of missing out—can obscure the underlying decision.'], ['What is the person actually relying on?', 'If there is no next buyer at a higher price, what remains?', 'Is the amount small because the risk is understood, or because the person is trying to make a large emotional bet feel harmless?'], { prompt: 'Which question helps distinguish investing from speculation?', options: [{ id: 'a', label: 'What claim, evidence, purpose, and uncertainty am I accepting?', isCorrect: true }, { id: 'b', label: 'How many people are excited about it?', isCorrect: false }, { id: 'c', label: 'Can I describe the trend in one sentence?', isCorrect: false }] }, { prompt: 'Ivy says, “I know it is speculative, but it will probably go up.” What is still missing?', options: [{ id: 'a', label: 'A louder community', strength: 'developing', feedback: 'Community excitement can increase pressure without improving the claim.' }, { id: 'b', label: 'A clear statement of what she relies on, what she could lose, and why it serves the goal', strength: 'strong', feedback: 'Naming the reliance and consequence makes the speculation visible instead of disguising it as certainty.' }, { id: 'c', label: 'A guarantee from the chart', strength: 'developing', feedback: 'Charts describe past movement; they do not guarantee the next buyer or result.' }] }, 'When excitement makes a financial opportunity feel urgent, I tend to…', 'Write two columns: evidence that supports the claim and pressure that makes you want to act. Do not combine them.', 'I can feel urgency without mistaking it for evidence.', 'The bright hall has taken something from them: the illusion that a gain is only a gain. Next, the Exchange tests emotion itself.', ['finraRisk', 'ftcScams', 'ftcCrypto']),

  lesson('The Emotional Price of a Falling Balance', 'A falling number can activate a story long before it reveals an outcome.', [
    'The Loss Gallery is quieter than the other halls. Every visitor receives a changing balance and a short sentence from their past. Ivy sees, “You always mess things up.” Eli sees, “You should have known better.”',
    'Neither sentence came from the market. Both feel attached to it anyway.',
    'Sage does not tell them to hold, sell, or buy. She asks them to notice the sequence: the number moves, the body reacts, the old story speaks, an action becomes urgent, and the future claim changes.',
    'They build a pause point: name the movement, identify the need for access, review the original purpose, check what changed in the underlying claim, and separate information from panic.',
  ], ['Emotions affect interpretation, timing, attention, and behavior during gains and losses.', 'A market movement is information about price, not a complete verdict about identity or worth.', 'A decision process can create space between feeling and action without denying the feeling.'], ['This appears during volatility, news events, peer comparison, financial regret, and moments when a person needs money.', 'Past scarcity or shame can make a temporary decline feel like proof of permanent failure.', 'Overconfidence after gains can create a different but equally important risk.'], ['What is the number telling you, and what is the old story adding?', 'What changed in the asset or goal, versus what changed in the emotion?', 'What would a pause protect: money, clarity, dignity, or the ability to make a non-reactive decision?'], { prompt: 'What is the purpose of a decision pause during volatility?', options: [{ id: 'a', label: 'To pretend the feeling is not real', isCorrect: false }, { id: 'b', label: 'To separate movement, evidence, need, and old stories before acting', isCorrect: true }, { id: 'c', label: 'To guarantee the next price direction', isCorrect: false }] }, { prompt: 'Ivy sees a sharp decline and wants to act immediately. What is the first useful separation?', options: [{ id: 'a', label: 'My identity is falling with the balance', strength: 'developing', feedback: 'The feeling may be real, but the balance is not a measurement of Ivy’s worth.' }, { id: 'b', label: 'What changed in the claim, what changed in the goal, and what is only a reaction', strength: 'strong', feedback: 'This creates a decision surface where evidence and emotion can both be acknowledged without being confused.' }, { id: 'c', label: 'Everyone else knows what to do', strength: 'developing', feedback: 'Crowd behavior can intensify pressure without providing a personal decision process.' }] }, 'A money movement that tends to activate an old story in me is…', 'Create a personal pause script: what you will check, what you will not do while flooded, and what question returns you to the original purpose.', 'I can notice a financial feeling without letting it become the whole explanation.', 'Sage takes them to the Provider Gate, where trust is supposed to be earned rather than performed.', ['finraRisk', 'finraNew']),

  lesson('Who Is Paid, Registered, and Responsible?', 'Trust is not the same thing as charm. A provider should be explainable, verifiable, and accountable.', [
    'The Provider Gate is lined with polished people who say “trust me” before they say what they do. Some manage money. Some sell products. Some teach. Some simply route people toward a platform.',
    'Eli asks which person has the best smile. Ivy asks which person has the highest testimonials. Sage hands them a checklist: role, compensation, registration or licensing where applicable, conflicts, documents, complaints, custody, and the exact promise being made.',
    'One booth answers plainly. Another becomes offended by ordinary questions. The Exchange marks both responses in different colors.',
  ], ['A financial professional, educator, salesperson, platform, and custodian may have different roles and incentives.', 'Registration, licensing, and disclosure checks can help verify a provider, but they do not guarantee a result.', 'How someone gets paid is part of the decision.'], ['This appears in brokerage services, financial advice, investment education, real estate, insurance-linked products, private offerings, and online communities.', 'Conflicts can exist even when a provider is legitimate.', 'A regulated provider can offer a risky product; verification is one layer, not the whole analysis.'], ['What does the provider do, and what are they not doing?', 'What happens if the provider is wrong, unavailable, conflicted, or gone?', 'Is the person asking for trust because the evidence is strong or because scrutiny is inconvenient?'], { prompt: 'What belongs in a provider check?', options: [{ id: 'a', label: 'Role, compensation, registration, conflicts, documents, and responsibility', isCorrect: true }, { id: 'b', label: 'Personality and follower count only', isCorrect: false }, { id: 'c', label: 'A promise that losses are impossible', isCorrect: false }] }, { prompt: 'A provider refuses to explain how they are paid. What is the clearest signal?', options: [{ id: 'a', label: 'The lack of transparency is itself relevant information', strength: 'strong', feedback: 'Compensation can influence incentives. Refusing a basic question is a decision fact.' }, { id: 'b', label: 'They must be trustworthy because they are confident', strength: 'developing', feedback: 'Confidence is not evidence of accountability.' }, { id: 'c', label: 'Ask only after sending money', strength: 'developing', feedback: 'Verification belongs before commitment.' }] }, 'The questions I would want answered before trusting a financial provider are…', 'Build a provider-check list with role, pay, registration, conflicts, documents, custody, complaints, and exit conditions.', 'I can require accountability before I hand over money or trust.', 'The Gate opens onto a room full of guarantees. Sage does not like the room.', ['finraNew', 'ftcScams', 'ftcCrypto']),

  lesson('The Promise That Cannot Be Promised', 'A guarantee is a claim about responsibility. Ask who carries the risk, under what terms, and what the promise excludes.', [
    'The Guarantee Room is the most crowded place in the Exchange. Every wall says CERTAIN. The floor is covered in tiny exclusions.',
    'Ivy notices that the strongest promises have the weakest explanations. Eli reads a phrase that sounds safe until he finds the word “subject to.”',
    'Sage teaches them to slow down at absolute language: guaranteed, no risk, cannot lose, passive, effortless, secret, limited, exclusive. “A promise can be honest, mistaken, incomplete, or fraudulent. The word itself does not decide which.”',
  ], ['No investment is free from risk; guarantees depend on the guarantor, terms, limits, and exclusions.', 'Past performance and forecasts are not guarantees of future results.', 'Urgency and certainty are persuasion tools that deserve verification.'], ['This appears in seminars, social media, private deals, precious metals, crypto pitches, coaching programs, and high-pressure sales.', 'Scams often combine urgency, authority, secrecy, testimonials, and promises of low risk.', 'A legitimate opportunity can still be a poor fit without being a scam.'], ['What exactly is guaranteed, by whom, and under what enforceable conditions?', 'What does the promise ask the buyer to ignore?', 'What would happen if the promised result does not occur?'], { prompt: 'What should happen when an opportunity promises high return with little or no risk?', options: [{ id: 'a', label: 'Treat the promise as a reason to slow down and verify', isCorrect: true }, { id: 'b', label: 'Assume the risk is hidden because the return is high', isCorrect: false }, { id: 'c', label: 'Act quickly before the opportunity disappears', isCorrect: false }] }, { prompt: 'A post says, “Guaranteed monthly income—only five spots left.” What is the strongest response?', options: [{ id: 'a', label: 'Save the post and send money before the deadline', strength: 'developing', feedback: 'Urgency is a pressure signal, not verification.' }, { id: 'b', label: 'Identify the claim, provider, compensation, risks, documents, and registration before considering it', strength: 'strong', feedback: 'The response turns a persuasive promise into a set of testable questions.' }, { id: 'c', label: 'Assume every income claim is fake', strength: 'developing', feedback: 'Skepticism is useful, but a blanket conclusion can replace examination with avoidance.' }] }, 'A promise that would make me slow down instead of speed up is…', 'Find three absolute words often used in financial persuasion. Rewrite each as a question that could be verified.', 'I can treat certainty language as a prompt for questions.', 'They have learned how to hear a promise. Now the final hall connects ownership to the money already moving through their lives.', ['ftcScams', 'ftcCrypto', 'finraRisk']),

  lesson('Investing Does Not Float Above Real Life', 'The future claim is built with present capacity: income, cash flow, debt, protection, and time.', [
    'The Exchange’s lower level is connected to every Root they have already visited. A line from present cash flow feeds the future hall. Another line from debt narrows it. A protection gate flashes when they ignore disruption. A savings reserve keeps a door from locking.',
    'Ivy feels the old pressure to make one investment solve everything. Sage points to the whole system. “Growth does not excuse a fragile present. A future claim cannot carry a job that today’s money is not able to perform.”',
    'Eli sees that investing is not a separate identity. It is one decision inside a life with bills, bodies, work, relationships, emergencies, and limits.',
  ], ['Investing decisions interact with income, cash flow, debt obligations, reserves, protection, and future goals.', 'The ability to leave money invested is partly a capacity question.', 'A financial system can be mathematically promising and practically unstable at the same time.'], ['This appears when people invest while carrying expensive debt, no reserves, unstable income, concentrated exposure, or insufficient protection.', 'It also appears when people delay every future decision because the present is not perfect.', 'The useful question is not “Am I allowed to invest?” but “What job must this money perform, and what capacity supports the choice?”'], ['Is the investment solving a future goal or being asked to rescue the present?', 'What happens to the plan during income loss, emergency expense, debt stress, or caregiving?', 'Which previous Root should be visible before this decision moves forward?'], { prompt: 'What does a practical investing decision include?', options: [{ id: 'a', label: 'Only the expected growth', isCorrect: false }, { id: 'b', label: 'The future goal and the present system that must support it', isCorrect: true }, { id: 'c', label: 'A refusal to think about the future until life is perfect', isCorrect: false }] }, { prompt: 'Ivy wants to invest money she may need to cover a fragile month. What should Sage keep visible?', options: [{ id: 'a', label: 'The investment’s excitement only', strength: 'developing', feedback: 'Excitement does not solve the timing problem.' }, { id: 'b', label: 'The present cash-flow gap, the future goal, and the consequence of needing access', strength: 'strong', feedback: 'The choice belongs inside the real system, not above it.' }, { id: 'c', label: 'A universal rule that investing is always right', strength: 'developing', feedback: 'RootWise does not replace the learner’s examination with a universal rule.' }] }, 'The present condition that matters most before I ask future money to grow is…', 'Make a one-page connection map between present income, cash flow, debt, protection, reserves, and the future goal.', 'I can connect future ownership to present capacity.', 'The lower level opens into a wide platform. Here the question is not whether to own, but what ownership must remain possible.', ['investorBasics', 'finraRisk', 'irsRetirement']),

  lesson('Growth Is Not the Same as Availability', 'Money can be growing and still be unavailable, illiquid, restricted, or badly timed for the life that needs it.', [
    'The Availability Platform shows two balances. One rises slowly behind glass. The other moves less but can be reached through an open door. Visitors keep comparing the numbers and ignoring the doors.',
    'Ivy imagines an emergency at the exact moment the higher balance is locked. Eli imagines an accessible balance losing purchasing power while it waits.',
    'Sage asks them to stop treating growth and access as enemies. Different dollars can have different jobs. The mistake is assigning a short-term job to a long-term container or a long-term job to money that must remain immediately available.',
  ], ['Liquidity is the ability to access or sell an asset with reasonable speed and without unacceptable loss or cost.', 'Growth and availability are separate dimensions of a financial decision.', 'A future plan can need both accessible resources and long-term ownership.'], ['This appears in retirement plans, property, certificates, private investments, business interests, and emergency reserves.', 'Access can be limited by market conditions, tax rules, penalties, buyers, paperwork, or the need to accept a lower price.', 'A high balance does not equal high financial flexibility.'], ['What if the money is needed earlier than planned?', 'What access cost would turn an apparent gain into a practical loss?', 'Is the desire for availability driven by a real need or by discomfort with uncertainty?'], { prompt: 'What is the key difference between growth and availability?', options: [{ id: 'a', label: 'They measure different jobs: future value and present access', isCorrect: true }, { id: 'b', label: 'Growth always matters more', isCorrect: false }, { id: 'c', label: 'Availability means the money cannot grow', isCorrect: false }] }, { prompt: 'Eli wants every dollar available at all times. What is the deeper question?', options: [{ id: 'a', label: 'Which goals need access and which goals can accept time?', strength: 'strong', feedback: 'The solution is not one universal container; it is matching each dollar’s job to its access and time needs.' }, { id: 'b', label: 'Whether growth is unnecessary', strength: 'developing', feedback: 'Growth may matter for long-term goals even though not every dollar belongs there.' }, { id: 'c', label: 'Whether he can avoid all uncertainty', strength: 'developing', feedback: 'No allocation removes all uncertainty.' }] }, 'A future goal that needs access and a future goal that needs time are different because…', 'Sort three fictional pools of money by access need, time horizon, and consequence if value falls or access is delayed.', 'I can give different dollars different jobs.', 'The Exchange now asks what you are willing to carry: uncertainty, responsibility, patience, and the possibility of changing course.', ['finraRisk', 'irsRetirement', 'treasury']),

  lesson('Capacity, Dependence, and the Ownership Load', 'Ownership can create options, but it can also create work, concentration, responsibility, and dependence.', [
    'The final hall before the platform is full of things people own but do not maintain. A property needs repairs. A business interest needs attention. A private investment needs documents. A fund needs monitoring. A family asset needs communication.',
    'Ivy says, “I thought ownership meant the asset worked for me.” Sage replies, “Sometimes. Sometimes you are the one working to keep the asset useful.”',
    'Eli maps his own capacity: time, knowledge, cash, emotional bandwidth, ability to wait, ability to absorb loss, and willingness to manage the claim. The map is smaller than the promise—and more honest.',
  ], ['Risk capacity is the ability to absorb a negative outcome; risk tolerance is how a person feels about uncertainty.', 'Ownership can create responsibilities, dependencies, and concentration alongside possible benefits.', 'The best-understood opportunity can still exceed present capacity.'], ['This appears in property, private businesses, collectibles, direct ownership, concentrated stock, alternative assets, and complex accounts.', 'A person can be financially capable in one area and overextended in another.', 'Delegating management changes the work; it does not remove fees, provider dependence, or responsibility to understand the arrangement.'], ['What capacity is the asset asking for?', 'What relationship, platform, tenant, provider, market, or system does it depend on?', 'What would happen if the owner had less time, money, health, or access than expected?'], { prompt: 'What belongs in an ownership-load check?', options: [{ id: 'a', label: 'Only the possible upside', isCorrect: false }, { id: 'b', label: 'Time, knowledge, money, dependence, responsibility, and downside capacity', isCorrect: true }, { id: 'c', label: 'Whether the asset looks impressive', isCorrect: false }] }, { prompt: 'Ivy can afford the entry price but not the ongoing work. What does that reveal?', options: [{ id: 'a', label: 'The opportunity may exceed her ownership capacity', strength: 'strong', feedback: 'Affordability at entry is not the same as capacity for the ongoing responsibility and downside.' }, { id: 'b', label: 'The asset is automatically a bad investment', strength: 'developing', feedback: 'The issue is fit and capacity, not a universal judgment about the asset.' }, { id: 'c', label: 'She should ignore the work because ownership creates freedom', strength: 'developing', feedback: 'Freedom can be reduced when the ownership load is hidden.' }] }, 'The ownership responsibility I am most likely to underestimate is…', 'Build an ownership-load map with entry cost, ongoing cost, time, knowledge, dependence, access, and exit conditions.', 'I can evaluate the load an opportunity places on the life carrying it.', 'They have crossed the bright part of the Exchange. The last platform asks them to choose a future system without being told what to buy.', ['finraRisk', 'finraNew', 'investorBasics']),

  lesson('The Ownership Map', 'A strong decision is not a product list. It is a map of purpose, claims, time, risk, cost, access, and capacity.', [
    'At the center of the Exchange, Ivy and Eli receive a blank map. It has no highlighted route and no “best” booth. It has spaces for future purpose, present capacity, claim, time horizon, risk, costs, access, dependence, evidence, and questions still unanswered.',
    'Ivy wants to fill it with a single bright line. Eli wants to leave it blank until certainty arrives. Sage places both hands on the map. “Choice does not require certainty. It requires enough understanding to see what you are choosing and what you are not.”',
    'They draw different routes for different futures. Some money stays accessible. Some may participate in long-term growth. Some choices remain open because the evidence is not ready. The map feels less dramatic than the first neon sign—and far more like something they can actually live with.',
    'The bell rings. No booth declares them winners. The Exchange simply records that they asked better questions before letting a future claim reorganize their present.',
  ], ['An ownership map connects purpose, claim, time, risk, cost, access, capacity, evidence, and responsibility.', 'Informed choice does not require certainty or a single universal route.', 'The learner’s capacity is measured by what they can now evaluate and decide independently.'], ['This map can be revisited when income, goals, health, family, laws, markets, or responsibilities change.', 'The same framework can examine traditional ownership, lending, pooled investments, property, alternatives, and non-owner paths to future security.', 'A changed decision is not automatically failure; it may reflect changed information or changed life conditions.'], ['What does the map make visible that excitement hid?', 'Which parts are known, assumed, unknown, or dependent on someone else?', 'What would make the learner revisit the route without shame or panic?'], { prompt: 'What is the final capability of Root Eight?', options: [{ id: 'a', label: 'Choose the investment Sage prefers', isCorrect: false }, { id: 'b', label: 'Evaluate future ownership choices independently with purpose, risk, cost, access, and responsibility in view', isCorrect: true }, { id: 'c', label: 'Avoid all risk forever', isCorrect: false }] }, { prompt: 'Ivy finishes the map and still has unanswered questions. What does an informed next step look like?', options: [{ id: 'a', label: 'Hide the questions so the decision feels complete', strength: 'developing', feedback: 'Unanswered questions are useful information; hiding them reduces decision capacity.' }, { id: 'b', label: 'Separate knowns from unknowns, investigate what matters, and keep the choice revisable', strength: 'strong', feedback: 'Informed choice can include pause, research, comparison, and revision.' }, { id: 'c', label: 'Choose the most exciting route to prove confidence', strength: 'developing', feedback: 'Confidence is not the same as capacity.' }] }, 'The future I want ownership or investing to support is… The questions I refuse to skip are…', 'Complete an ownership map for one real or fictional future goal. Mark every field as known, assumed, unknown, or dependent on another person or system.', 'I can evaluate ownership as a path to choice—not a promise, identity, or escape hatch.', 'Ivy and Eli leave the Exchange carrying a map instead of a slogan. Beyond the next bridge, Root Nine will examine ownership and financial freedom at greater depth.', ['investorBasics', 'allocationGuide', 'finraRisk', 'finraNew', 'ftcScams']),
];

function slugify(value) { return value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }

export const rootEightLessons = lessons.map((item, index) => ({
  ...item,
  number: index + 1,
  displayNumber: `8.${index + 1}`,
  key: `exchange-${String(index + 1).padStart(2, '0')}-${slugify(item.title)}`,
  part: rootEightParts.find((part) => index + 1 >= part.range[0] && index + 1 <= part.range[1]),
  sources: (item.sourceKeys || []).map((key) => sources[key]),
}));

export const rootEightQuickPrompts = [
  'Separate the claim from the promise',
  'Show me what could change the value',
  'Find the hidden cost or access limit',
  'Compare growth with availability',
  'Help me ask better provider questions',
];

export function rootEightNarration(lesson) { return [lesson.sageOpen, ...lesson.story, ...lesson.understand, lesson.growth].join('\n\n'); }
